import{DERBY_CONFIG as E}from"./config.min.js";export function outlineOf(s,i=E){const n=i.kit,r=n.wheel.radius-n.axleHeight,e=s.map(([o,,a])=>[-o,r+a]),t=s.slice().reverse().map(([o,a])=>[-o,r+a]);return e.concat(t)}export function wheelSpots(s,i=E){const n=i.kit.wheel,r=s.dims.wheelGap/2+n.thickness/2+.001,e=[];for(const t of[s.frontAxle,s.rearAxle])e.push([-t,n.radius,-r],[-t,n.radius,r]);return e}let h=null;export function buildCarMesh(s,i,{color:n=13421772,shadows:r=!1}={},e=E){const t=new THREE.Group;t.name="car";const o=outlineOf(s.stations,e),a=new THREE.Shape;a.moveTo(o[0][0],o[0][1]);for(let c=1;c<o.length;c++)a.lineTo(o[c][0],o[c][1]);a.closePath();const f=i.body.width,u=new THREE.ExtrudeGeometry(a,{depth:f,bevelEnabled:!1,curveSegments:1});u.translate(0,0,-f/2);const m=new THREE.MeshStandardMaterial({color:n,roughness:.42,metalness:.08}),T=new THREE.Mesh(u,m);T.castShadow=r,t.add(T);const l=e.kit.wheel;h||(h=new THREE.CylinderGeometry(l.radius,l.radius,l.thickness,20),h.rotateX(Math.PI/2));const x=new THREE.MeshStandardMaterial({color:e.look.wheel,roughness:.6}),H=wheelSpots(i,e).map(([c,p,w])=>{const d=new THREE.Mesh(h,x);return d.position.set(c,p,w),d.castShadow=r,t.add(d),d});return{group:t,wheels:H,roll(c){const p=-c/l.radius;for(const w of H)w.rotation.z=p},dispose(){u.dispose(),m.dispose(),x.dispose()}}}
